package net.civeira.phylax.feature.observe.observedslo.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ObjectiveVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property objective of observed slo ")
  void test_objective_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ObjectiveVO.tryFrom(null));
    Assertions.assertEquals(1, ObjectiveVO.from(1).getObjective());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ObjectiveVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", ObjectiveVO.from(1).toString());
  }
}
